<?php require_once 'functions.php'; require_login(); if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['close_id'])){$id=(int)$_POST['close_id'];$st=$pdo->prepare("UPDATE items SET status='closed' WHERE id=? AND user_id=? AND status='active'");$st->execute([$id,$_SESSION['user']['id']]);flash($st->rowCount()?'Report closed.':'Could not close that report.','success');header('Location: my_reports.php');exit;}
$st=$pdo->prepare('SELECT i.*, (SELECT COUNT(*) FROM claims c WHERE c.item_id=i.id) claim_count FROM items i WHERE i.user_id=? ORDER BY i.created_at DESC');$st->execute([$_SESSION['user']['id']]);$items=$st->fetchAll();page_header('My reports'); ?><div class="section-head"><div><p class="eyebrow">YOUR ACTIVITY</p><h1>My reports</h1><p class="muted">Manage the items you have reported.</p></div><a class="button" href="report.php">＋ New report</a></div><div class="panel table-wrap"><table><thead><tr><th>Item</th><th>Type</th><th>Date</th><th>Status</th><th>Claims</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><a class="text-link" href="item.php?id=<?=(int)$i['id']?>"><?=e($i['title'])?></a><div class="muted small"><?=e($i['place'])?></div></td><td><?=e(ucfirst($i['item_type']))?></td><td><?=e($i['item_date'])?></td><td><span class="pill neutral"><?=e($i['status'])?></span></td><td><?=(int)$i['claim_count']?></td><td><a class="text-link" href="item.php?id=<?=(int)$i['id']?>">View</a> <?php if($i['status']==='active'): ?><form class="inline-form" method="post" onsubmit="return confirm('Close this report?')"><button class="text-button" name="close_id" value="<?=(int)$i['id']?>">Close</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="6">You have not posted any reports yet.</td></tr><?php endif; ?></tbody></table></div><?php page_footer(); ?>
